/*
 * A115302  Permutation of natural numbers generated by 3-rowed array shown
 *          below.
 * https://oeis.org/A115302
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = { 1, 4, 2 for n = 1, 2, 3; * 3b + 4 if (n-1)%3 == 0 and b
 *            >= 1, * 3b + 2 if (n-1)%3 == 1, * 3b if (n-1)%3 == 2, * where b
 *            = floor((n-1)/3)
 * Range:     u8 n <= 63, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Block index (0 based) and position inside the block. */
    idx_t b = (n - 1) / 3;
    idx_t r = (n - 1) % 3;

    /* Handle the first block explicitly; the remaining blocks follow a
       uniform pattern. */
    if (b == 0) {
        if (r == 0) return 1;   /* a(1) = 1 */
        if (r == 1) return 4;   /* a(2) = 4 */
        return 2;               /* r == 2 → a(3) = 2 */
    }

    /* For blocks b >= 1 the values are 3b+4, 3b+2, 3b. */
    idx_t base = 3 * b;
    seq_t val;
    if (r == 0) {
        val = (seq_t)base + 4;
    } else if (r == 1) {
        val = (seq_t)base + 2;
    } else { /* r == 2 */
        val = (seq_t)base;
    }
    return val;
}
